impl Solution {
    pub fn largest_integer(nums: Vec<i32>, k: i32) -> i32 {
        let len = nums.len();
        if k == 1 {
            let mut bucket = [0; 51];
            for &n in &nums {
                bucket[n as usize] += 1;
            }
            bucket
                .into_iter()
                .enumerate()
                .rev()
                .find_map(|(n, c)|
                    (c == 1).then_some(n as i32)
                )
                .unwrap_or(-1)
        } else if k == len as i32 {
            nums.into_iter().max().unwrap_or(-1)
        } else {
            let first = nums[0];
            let last = nums[len-1];
            if first == last {
                return -1;
            }
            let (seen_first, seen_last) = nums[1..len - 1].iter().fold((false, false), |(sf, sl), &x| {
                (sf || x == first, sl || x == last)
            });

            let first = if seen_first { -1 } else { first };
            let last = if seen_last { -1 } else { last };
            first.max(last)
        }
    }
}

